Page_CommonActRechargeRewardView = class("Page_CommonActRechargeRewardView",Page_CommonActViewBase)

function Page_CommonActRechargeRewardView:GetPageName()
    return "Page_CommonActRechargeRewardView"
end

function Page_CommonActRechargeRewardView:initialize()

end

function Page_CommonActRechargeRewardView:OnAwake()
    self.ScrollView_V= UIUtil.GetTypeChildWightInputPath("ScrollView_V", self.gameObject, typeof(MoreRowScrollView))
    RechargeRewardManager:Get():SetActData(self.actConfig.C_ID)
end

function Page_CommonActRechargeRewardView:RequestOpen()
    RechargeRewardManager:Get():SetActData(self.actConfig.C_ID)
    RechargeRewardManager:Get():SetCurActData(self.actConfig.C_ID)
    CommonFestivalSubSystem:Get():SendMsg_ActSumCharge(self.actConfig.C_ID)
end

function Page_CommonActRechargeRewardView:RefreshRedPointID(Active)
    local actData = RechargeRewardManager:Get():GetActData(self.actConfig.C_ID)
    local redPointID = actData.sumType<1000 and RedPointID.S_ActSingleDayRechargerReward or RedPointID.S_ActRechargerReward
    RedPointManager:Get():UpdateValue(redPointID,Active)
end

function Page_CommonActRechargeRewardView:Refresh()
    self.FreeGift = CommonHelper:HButtonSetCallback("FreeGift",self.gameObject,function(btn)
        CommonFestivalSubSystem:Get():SendMsg_ActSumChargeGift(self.actConfig.C_ID,0,0)
    end)
    local actData= RechargeRewardManager:Get():GetActData()
    local isSingleDay = actData.sumType<1000
    local titleStr= isSingleDay and CommonHelper:GetTempStr_Default(TemplateStringID.RechargeRewardSingleDayTitle) or CommonHelper:GetTempStr_Default(TemplateStringID.RechargeRewardTitle)
    CommonHelper:SetText("###title",self.gameObject,titleStr)


    ---宝箱领取标记0未1已领
    CommonHelper:SetHButtonEnable(self.FreeGift,actData.boxGift==0)
    CommonHelper:SetGameObjectActive("RedPoint1",self.FreeGift.gameObject,actData.boxGift==0)
    CommonHelper:SetGameObjectActive("AlreadyReceived",self.FreeGift.gameObject,actData.boxGift==1)

    ---@type table<number,RechargeRewardData>
    local rechargeRewardDataTable = RechargeRewardManager:Get():GetRechargeRewardDataTable()
    CommonHelper:InitMoreRowScrollView(self.ScrollView_V,  #rechargeRewardDataTable, 1,function(dataIndex, itemObj, scroll)
        self:UpdateScrollView_V(itemObj,dataIndex)
    end,false,nil,RechargeRewardManager:Get():GetRechargeIsResetFlag())
end

function Page_CommonActRechargeRewardView:OnOpen()
    CommonHelper:SetText("time/###time", self.gameObject,self:GetDataTimeString())
    self:Refresh()
end

function Page_CommonActRechargeRewardView:UpdateScrollView_V(itemObj,index)
    local actData= RechargeRewardManager:Get():GetActData()
    local tableIndex = index+1
    ---@type RechargeRewardData
    local rechargeRewardData = RechargeRewardManager:Get():GetRechargeRewardDataByIndex(tableIndex)

    CommonHelper:SetText("###rewardtitle",itemObj,CommonHelper:GetTempStr_Default(TemplateStringID.RechargeRewardTargetCost, rechargeRewardData.CurrencyType,rechargeRewardData.sumVal))
    local value = tonumber(actData.curSumVal) >rechargeRewardData.sumVal and rechargeRewardData.sumVal or actData.curSumVal
    value =  tonumber(value)  <= 0 and 0 or value
    CommonHelper:SetText("###progress",itemObj,string.format(CommonHelper:GetTempStr_Default(TemplateStringID.RechargeRewardProgress),value))
    CommonHelper:SetText("###Idx",itemObj,string.format("%02d",index+1))

    local sliderValue =tonumber(actData.curSumVal) /rechargeRewardData.sumVal
    sliderValue = sliderValue==0 and -1 or sliderValue
    CommonHelper:SetSlider("Slider",itemObj,sliderValue)

    CommonHelper:SetGameObjectActive("UnFinished",itemObj,rechargeRewardData.state == RechargeRewardType.UnFinished)
    CommonHelper:SetGameObjectActive("BtnUnclaimed",itemObj,rechargeRewardData.state == RechargeRewardType.Unclaimed)
    CommonHelper:SetGameObjectActive("AlreadyReceived",itemObj,rechargeRewardData.state == RechargeRewardType.AlreadyReceived)
    CommonHelper:SetGameObjectActive("RedPoint1",itemObj,rechargeRewardData.state == RechargeRewardType.Unclaimed)
    CommonHelper:HButtonSetCallback("BtnUnclaimed",itemObj,function()
        CommonFestivalSubSystem:Get():SendMsg_ActSumChargeGift(self.actConfig.C_ID,1,index)
    end)
    local ScrollView_H= UIUtil.GetTypeChildWightInputPath("ScrollView_H", itemObj, typeof(MoreRowScrollView))
    CommonHelper:InitMoreRowScrollView(ScrollView_H,  #rechargeRewardData.rewardPropIdTable, 1,function(rewardIndex, itemChild, scroll)
        local propId,propNum=rechargeRewardData:GetPropByIndex(rewardIndex+1)
        local propType ,configData = CommonHelper:GetPropTypeById(propId)
        local name =""
        if propType==PropType.TracKSegment then
            name = configData.name
        elseif propType==PropType.Part then
            name = configData.partname
        elseif propType==PropType.Article then
            name = configData.name
        end
        local param = Param_ItemArticleParam()
        param.moduleId = self:GetUIModuleID()
        param.id = propId
        param.count=propNum
        CommonHelper:SetItemComGroup(itemChild,self:GetUIModuleID(),propId,  param,function()
            CommonHelper:ShowPartInfoByCfgId(propId, UIModuleID.CommonActRechargeReward, false)
        end)
    end)
end

function Page_CommonActRechargeRewardView:GetRedPointActive()
    local actData = RechargeRewardManager:Get():GetActData(self.actConfig.C_ID)
    if actData == nil then
        return false
    end
    local redPointID = actData.sumType<1000 and RedPointID.S_ActSingleDayRechargerReward or RedPointID.S_ActRechargerReward
    return RedPointManager:Get():GetValue(redPointID)
end

function Page_CommonActRechargeRewardView:OnClose()
    log("Page_CommonActRechargeRewardView:OnClose")
end